  ('丕顯', '비현', '크게 밝음. 크게 나타남.', '2026-11-18T00:36:53+00:00'::timestamptz),
  ('丕顯德', '비현덕', '크게 밝은 덕. 훌륭한 덕.', '2026-11-18T00:36:53+00:00'::timestamptz),
